import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"贡献者可移植性注记","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/portability.md","filePath":"zh/dev/portability.md"}'),t={name:"zh/dev/portability.md"};function r(i,e,n,l,s,p){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="贡献者可移植性注记" tabindex="-1">贡献者可移植性注记 <a class="header-anchor" href="#贡献者可移植性注记" aria-label="Permalink to &quot;贡献者可移植性注记&quot;">​</a></h1><p>这棵树在本地以 GCC 14.x 构建，在 CI 上以更新的工具链构建。已有 三类差异咬过人 - 把它们记在心里：</p><h2 id="_1-更新-gcc-上更严格的警告类" tabindex="-1">1. 更新 GCC 上更严格的警告类 <a class="header-anchor" href="#_1-更新-gcc-上更严格的警告类" aria-label="Permalink to &quot;1. 更新 GCC 上更严格的警告类&quot;">​</a></h2><p><code>-Waddress-of-packed-member</code>（自 GCC 9 起属于 <code>-Wall</code>，在更新 的版本中执行得更严）：把 packed 结构体指针转换成自然对齐的类型 在 <code>-Werror</code> 下是错误。multiboot2 的标签类型全部声明为 <code>__attribute__((packed))</code>，正是出于这个原因 - 包括 mmap 标签 （4x u32，布局不变）和经由 packed 标签类型而非裸 <code>u32*</code> 转换的 BASIC_MEMINFO 读取器。</p><p>规则：当你转换一个来自 packed 内存的指针时，目标也要是 packed 类型。</p><h2 id="_2-更严格的汇编器-binutils-gas" tabindex="-1">2. 更严格的汇编器（binutils/GAS） <a class="header-anchor" href="#_2-更严格的汇编器-binutils-gas" aria-label="Permalink to &quot;2. 更严格的汇编器（binutils/GAS）&quot;">​</a></h2><p><code>setcc</code>/<code>setc</code> 只接受 BYTE 寄存器。rdrand 包装曾把标志声明为 <code>u32</code> 并使用 <code>&quot;=q&quot;</code> 约束 - 旧 GAS 静默截断到字节子寄存器，新 GAS 拒绝该操作数大小。现在它是 <code>u8</code>。</p><p>规则：setcc 类标志用 <code>u8</code>，约束 <code>&quot;=q&quot;</code>。</p><h2 id="_3-工具链布局假设" tabindex="-1">3. 工具链布局假设 <a class="header-anchor" href="#_3-工具链布局假设" aria-label="Permalink to &quot;3. 工具链布局假设&quot;">​</a></h2><p><code>OC_TOOLS</code> 可以指向一棵可重定位的树（<code>&lt;root&gt;/usr/{bin,lib}</code>） 或一个系统根（<code>/usr</code> 下直接有 <code>{bin,lib}</code>）。embed_grub 生成器 会探测两种布局 - 不要假设任何一种。</p><h2 id="编译标志契约" tabindex="-1">编译标志契约 <a class="header-anchor" href="#编译标志契约" aria-label="Permalink to &quot;编译标志契约&quot;">​</a></h2><p>内核标志固定在 Makefile 中： <code>-ffreestanding -fno-stack-protector -fno-pie -fno-pic -mno-red-zone -mno-sse -mno-mmx -mno-3dnow -mcmodel=kernel -fno-asynchronous-unwind-tables -Wall -Wextra -Werror -O2 -g -std=gnu11</code>。新标志属于 Makefile（一处），不要散落在各个文件 里。</p><h2 id="交叉构建" tabindex="-1">交叉构建 <a class="header-anchor" href="#交叉构建" aria-label="Permalink to &quot;交叉构建&quot;">​</a></h2><p><code>make ARCH=arm64</code> / <code>ARCH=riscv</code> 使用 aarch64/riscv64 交叉 工具链和它们自己的链接规则（<code>--hash-style=sysv --build-id=none</code>；<code>-n</code> 与 PHDR 布局不兼容）。点亮用的 shell 是 真实的（PL011/NS16550A 除数、定时器计数、心跳）但有意保持 最小 - x86_64 才是功能完备的架构。</p>',14)])])}const _=o(t,[["render",r]]);export{u as __pageData,_ as default};
